#include "map_core.h"
#include <stdlib.h>
#include <string.h>
#include <math.h>
struct Map { MapConfig c; Cell *cells; unsigned char *marks; };
Map *map_create(const MapConfig *c) { if(!c||c->width<=0||c->height<=0||c->width>10000||c->height>10000||c->resolution<=0||c->min_log>c->max_log) return NULL; Map *m=calloc(1,sizeof(*m)); if(!m)return NULL; m->c=*c; size_t n=(size_t)c->width*c->height; m->cells=calloc(n,sizeof(Cell)); m->marks=calloc(n,1); if(!m->cells||!m->marks){map_destroy(m);return NULL;} return m; }
void map_destroy(Map *m){if(m){free(m->cells);free(m->marks);free(m);}}
void map_reset(Map *m){if(m){size_t n=(size_t)m->c.width*m->c.height;memset(m->cells,0,n*sizeof(Cell));memset(m->marks,0,n);}}
/* Clip segment in continuous grid coordinates. The upper boundary is exclusive. */
static int clip(float *x0,float *y0,float *x1,float *y1,float w,float h){float dx=*x1-*x0,dy=*y1-*y0,t0=0,t1=1; float p[4]={-dx,dx,-dy,dy},q[4]={*x0,w-0.0001f-*x0,*y0,h-0.0001f-*y0}; for(int i=0;i<4;i++){if(fabsf(p[i])<1e-12f){if(q[i]<0)return 0;}else{float t=q[i]/p[i];if(p[i]<0){if(t>t1)return 0;if(t>t0)t0=t;}else{if(t<t0)return 0;if(t<t1)t1=t;}}} float x=*x0,y=*y0;*x0=x+t0*dx;*y0=y+t0*dy;*x1=x+t1*dx;*y1=y+t1*dy;return 1;}
int map_update(Map *m,Pose pose,const Ray *rays,int count,uint32_t frame){if(!m||count<0||(!rays&&count)||!isfinite(pose.x)||!isfinite(pose.y)||!isfinite(pose.theta))return -1; MapConfig c=m->c; int n=c.width*c.height;memset(m->marks,0,(size_t)n);for(int i=0;i<count;i++){Ray r=rays[i];if(!isfinite(r.angle)||!isfinite(r.distance)||r.distance<=0)continue;float a=pose.theta+r.angle;float x0=(pose.x-c.origin_x)/c.resolution,y0=(pose.y-c.origin_y)/c.resolution;float x1=(pose.x+r.distance*cosf(a)-c.origin_x)/c.resolution,y1=(pose.y+r.distance*sinf(a)-c.origin_y)/c.resolution;int hit=r.hit && x1>=0&&x1<=c.width&&y1>=0&&y1<=c.height; if(!clip(&x0,&y0,&x1,&y1,(float)c.width,(float)c.height))continue;int x=(int)floorf(x0),y=(int)floorf(y0),ex=(int)floorf(x1),ey=(int)floorf(y1);int dx=abs(ex-x),sx=x<ex?1:-1,dy=-abs(ey-y),sy=y<ey?1:-1,err=dx+dy;for(;;){int idx=y*c.width+x; unsigned char v=(x==ex&&y==ey&&hit)?2:1;if(m->marks[idx]<v)m->marks[idx]=v;if(x==ex&&y==ey)break;int e=2*err;if(e>=dy){err+=dy;x+=sx;}if(e<=dx){err+=dx;y+=sy;}}}for(int i=0;i<n;i++)if(m->marks[i]){Cell *p=&m->cells[i];p->log_odds+=m->marks[i]==2?c.occupied_delta:c.free_delta;if(p->log_odds<c.min_log)p->log_odds=c.min_log;if(p->log_odds>c.max_log)p->log_odds=c.max_log;p->observed=1;p->last_frame=frame;}return 0;}
int map_copy(const Map *m,Cell *out,int count){if(!m||!out||count<m->c.width*m->c.height)return -1;memcpy(out,m->cells,(size_t)m->c.width*m->c.height*sizeof(Cell));return 0;}
